    count = expRecur(n)
    println("指数阶（递归实现）的操作数量 = $count")

    count = logarithmic(n)
    println("对数阶（循环实现）的操作数量 = $count")
    count = logRecur(n)
    println("对数阶（递归实现）的操作数量 = $count")

    count = linearLogRecur(n)
    println("线性对数阶（递归实现）的操作数量 = $count")

    count = factorialRecur(n)
